/* Replace dbo.employee from EmployeeList CSV.
   name_normalized is left NULL. department_id is a stable 1-20 hash of employee_code.
   History is cleared first because FK_history_employee blocks employee deletes. */
SET NOCOUNT ON;

IF EXISTS (
    SELECT 1 FROM sys.columns
    WHERE object_id = OBJECT_ID('dbo.employee') AND name = 'name_normalized' AND is_nullable = 0
)
    ALTER TABLE dbo.employee ALTER COLUMN name_normalized NVARCHAR(200) NULL;
GO

DELETE FROM dbo.history;
DELETE FROM dbo.employee;
DBCC CHECKIDENT ('dbo.employee', RESEED, 0) WITH NO_INFOMSGS;
DBCC CHECKIDENT ('dbo.history',  RESEED, 0) WITH NO_INFOMSGS;
GO
